{
  "avaliacoes": [
    {
      "id": "Eeb6e69374cea5cb5",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Quando houver contingenciamento de elemento crítico de segurança operacional, recomenda-se conhecer todos os elementos contingenciados, analisar criticamente os contingenciamentos e restaurar a condição original de projeto, sanando a degradação.",
          "trechos": [
            "Eeb6e69374cea5cb5:0:697"
          ],
          "condicoes": [
            "aplica-se ao contexto de lições apresentadas no Relatório Anual de Segurança Operacional de 2021"
          ],
          "limites": [
            "o trecho não detalha método de análise crítica nem critérios objetivos para priorização dos contingenciamentos"
          ]
        },
        {
          "proposicao": "Em casos excepcionais em que a condição de projeto do elemento crítico não seja restaurada, deve-se garantir que as medidas de controle de risco permaneçam adequadas para manter o risco na zona ALARP até o restabelecimento completo do elemento crítico.",
          "trechos": [
            "Eeb6e69374cea5cb5:0:697"
          ],
          "condicoes": [
            "aplica-se apenas a casos excepcionais em que não for possível restaurar de imediato a condição de projeto",
            "a manutenção do risco em ALARP é transitória, até o reestabelecimento completo do elemento crítico"
          ],
          "limites": [
            "a fonte não apresenta critérios quantitativos para demonstrar adequação das medidas nem método de verificação de ALARP"
          ]
        },
        {
          "proposicao": "Para novas unidades contratadas para construção e intervenção em poços, o relatório recomenda avaliar a adequação ao gerenciamento de integridade nas etapas do ciclo de vida com presença de sonda, com atenção a auditorias de comissionamento prévias ao início das operações, à integração operador-contratada, ao treinamento da força de trabalho e ao alinhamento de requisitos de contratação com melhores práticas da indústria.",
          "trechos": [
            "Eeb6e69374cea5cb5:697:1387"
          ],
          "condicoes": [
            "referido ao contexto de contratação de novas unidades por novos operadores",
            "voltado às etapas do ciclo de vida com presença de sonda"
          ],
          "limites": [
            "o trecho não define critérios de seleção, conteúdo mínimo das auditorias nem indicadores de treinamento ou integração"
          ]
        }
      ]
    },
    {
      "id": "E78483ced0137641e",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "A Nota Técnica define barreira como mecanismo físico ou procedimento administrativo projetado ou executado para impedir ou mitigar acidentes, tratando 'controles' e 'salvaguardas' como sinônimos.",
          "trechos": [
            "E78483ced0137641e:1395:2088"
          ],
          "condicoes": [
            "aplica-se às definições constantes da Nota Técnica nº 4/2022 da ANP"
          ],
          "limites": [
            "o trecho não diferencia critérios de desempenho entre barreiras físicas e administrativas"
          ]
        },
        {
          "proposicao": "Barreira crítica é definida como a barreira que atende aos critérios definidos pelo operador para ser considerada elemento crítico, em consonância com o SGSO no item de identificação dos elementos críticos de segurança operacional.",
          "trechos": [
            "E78483ced0137641e:1395:2088"
          ],
          "condicoes": [
            "depende dos critérios definidos pelo próprio operador",
            "a definição é vinculada ao enquadramento do SGSO mencionado na nota"
          ],
          "limites": [
            "o trecho não explicita quais são esses critérios do operador"
          ]
        },
        {
          "proposicao": "A funcionalidade da barreira é definida como a capacidade de desempenhar sua função conforme projetada, incluindo confiabilidade e premissas estabelecidas nas análises e estudos de risco; a Nota também distingue diagnóstico geral, voltado a todas as barreiras identificadas, e diagnóstico específico, voltado a barreiras do tema analisado.",
          "trechos": [
            "E78483ced0137641e:1395:2088",
            "E78483ced0137641e:2088:2447"
          ],
          "condicoes": [
            "aplica-se às definições conceituais da nota técnica"
          ],
          "limites": [
            "o trecho não apresenta método de teste, critérios mínimos de confiabilidade nem periodicidade de avaliação"
          ]
        }
      ]
    },
    {
      "id": "Edc38c09f4f029ec5",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Recomenda-se estabelecer simulados periódicos de emergência abrangendo todos os cenários acidentais identificados, inclusive cenários com múltiplos feridos e fatalidades, com acionamento de recursos externos e tratamento corretivo dos resultados para melhoria contínua da resposta.",
          "trechos": [
            "Edc38c09f4f029ec5:0:694"
          ],
          "condicoes": [
            "aplica-se ao contexto de recomendações do relatório de investigação do FPSO Cidade de São Mateus",
            "os simulados devem contemplar recursos externos à plataforma"
          ],
          "limites": [
            "a fonte não define periodicidade mínima nem critérios de aceitação do desempenho nos simulados"
          ]
        },
        {
          "proposicao": "As recomendações incluem conscientizar periodicamente o pessoal de bordo sobre os riscos dos cenários contemplados no procedimento de resposta à emergência e proibir a liberação das pessoas às atividades normais antes do controle total da emergência.",
          "trechos": [
            "Edc38c09f4f029ec5:0:694",
            "Edc38c09f4f029ec5:694:1389"
          ],
          "condicoes": [
            "relacionado aos cenários acidentais contemplados no procedimento de resposta à emergência da unidade"
          ],
          "limites": [
            "o trecho não especifica conteúdo, frequência ou forma de comprovação da conscientização"
          ]
        },
        {
          "proposicao": "No projeto das unidades, recomenda-se avaliar refúgios temporários e enfermarias contra efeitos de sobrepressão, reduzir a exposição de pessoas em pontos de encontro aos riscos de cenários acidentais ou de seus escalonamentos e definir pontos de encontro alternativos identificados no plano de resposta.",
          "trechos": [
            "Edc38c09f4f029ec5:694:1389",
            "Edc38c09f4f029ec5:1389:2088"
          ],
          "condicoes": [
            "aplica-se à fase de projeto e ao planejamento de resposta à emergência",
            "os pontos de encontro alternativos devem constar no plano de resposta da unidade"
          ],
          "limites": [
            "a fonte não fornece critérios de dimensionamento, resistência ou localização aceitável desses refúgios e pontos de encontro"
          ]
        }
      ]
    },
    {
      "id": "E4c62d9d891e295cf",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "Entre as condicionantes comumente impostas para o início das operações de unidades de produção, o relatório destaca comissionamento, teste e aprovação do sistema de detecção, implementação das recomendações contidas nas análises de riscos, instalação de todas as proteções passivas contra incêndio, realização de auditoria de barreiras e conclusão de procedimento de start-up.",
          "trechos": [
            "E4c62d9d891e295cf:1395:2095",
            "E4c62d9d891e295cf:2095:2329"
          ],
          "condicoes": [
            "aplica-se às condicionantes comumente impostas no contexto descrito para início das operações"
          ],
          "limites": [
            "o trecho não detalha critérios de aprovação de cada item nem indica que a lista seja exaustiva para todas as instalações"
          ]
        },
        {
          "proposicao": "As auditorias de pré-operação descritas foram realizadas na fase de comissionamento das unidades, inclusive em estaleiros e antes de certas operações específicas, indicando uso dessa etapa como momento de verificação prévia ao início operacional.",
          "trechos": [
            "E4c62d9d891e295cf:0:695",
            "E4c62d9d891e295cf:695:1395"
          ],
          "condicoes": [
            "referido às auditorias pré-operacionais realizadas em 2019"
          ],
          "limites": [
            "o trecho descreve a prática observada em 2019 e não explicita um procedimento completo aplicável a todos os casos"
          ]
        },
        {
          "proposicao": "Entre os principais desvios observados nas ações de pré-operação, o relatório aponta falha no entendimento e implementação do conceito ALARP.",
          "trechos": [
            "E4c62d9d891e295cf:2095:2329"
          ],
          "condicoes": [
            "aplica-se aos desvios principais observados nas ações relatadas"
          ],
          "limites": [
            "o trecho não descreve quais falhas específicas ocorreram nem como corrigir o entendimento e a implementação de ALARP"
          ]
        }
      ]
    },
    {
      "id": "E961762e6a3f31009",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "No cenário analisado de fogo e explosão na casa de bombas do FPSO Cidade de São Mateus, o estudo citado no relatório concluiu que a probabilidade de escalonamento seria maior para explosão do que para incêndio.",
          "trechos": [
            "E961762e6a3f31009:0:694"
          ],
          "condicoes": [
            "aplica-se ao cenário específico da casa de bombas dessa unidade"
          ],
          "limites": [
            "trata-se de resultado específico da instalação investigada e não de regra geral para outros FPSOs ou cenários"
          ]
        },
        {
          "proposicao": "No mesmo cenário, o estudo considerou que o pessoal presente na casa de bombas seria fatalmente ferido, enquanto não haveria fatalidades imediatas para o pessoal no refúgio temporário ou no deck principal.",
          "trechos": [
            "E961762e6a3f31009:0:694"
          ],
          "condicoes": [
            "aplica-se às hipóteses e consequências consideradas no cenário específico analisado"
          ],
          "limites": [
            "as conclusões dependem das premissas do estudo e do arranjo da unidade, não sendo generalizáveis sem nova análise"
          ]
        },
        {
          "proposicao": "O relatório registra que, para a exposição normal de pessoas ao cenário de fogo e explosão na casa de bombas, foi obtido um nível de risco médio anual de 6,71×10^-6, valor que o estudo enquadrou abaixo da região de ALARP conforme a faixa nele adotada.",
          "trechos": [
            "E961762e6a3f31009:0:694"
          ],
          "condicoes": [
            "aplica-se ao estudo e ao critério de enquadramento utilizados nesse relatório de investigação",
            "refere-se à exposição normal de pessoas ao cenário específico"
          ],
          "limites": [
            "o valor e a faixa de ALARP citados pertencem ao estudo do caso e não devem ser convertidos em critério brasileiro universal de aceitabilidade"
          ]
        }
      ]
    }
  ],
